                //FOR TIMER
                else if (datas[i].function_in_elements_list[y].type === "Timer") {
                    if (datas[i].function_in_elements_list[y].info === "LessThan" && datas[i].function_in_elements_list[y].detail > msg._id ||
                        datas[i].function_in_elements_list[y].info === "MoreThan" && datas[i].function_in_elements_list[y].detail < msg._id) {
                        msg.payload = 1;
                        msg.delay = datas[i].function_in_elements_list[y].debounce * 1000;
