                    msg.id_function_in = datas[i].function_in_elements_list[y]._id;
                    msg.id_function = id_function;
                }

                //FOR TRIGGER, MECANISM, VIDEO, SOUND, IMAGE
                else if (datas[i].function_in_elements_list[y].info === msg._id) {
