                "game_duration": global.get('current_game.game_duration')
            }
        }
        node.send([msg, null]);
    }

    else if (msg.payload.game_state === "pitch") {
        msg.game_log.id = msg.game_log.time;
        global.set("current_game.game_state", msg.game_log.action);
        global.set("current_game.game_id", msg.game_log.id);

