                "game_state": msg.game_log.action,
                "game_duration": global.get('current_game.game_duration')
            }
        }
        node.send([msg, null]);
    }

    else if (msg.payload.game_state === "reset" || msg.payload.game_state === "setup") {
        msg.game_log.id = msg.game_log.time;
        global.set("current_game.game_state", "stopped");
        global.set("current_game.game_id", "reset");

        msg.payload = {
            _id: "init",
            game_id: "reset",
            game_state: "stopped"
        }
        node.send([null, msg]);
    }
}

else {
