    if (msg.payload.game_state === "pitch" && global.get('current_game.game_state') !== "pitch") {
        global.set("current_game.game_state", msg.game_log.action);
    }

    else if (msg.payload.game_state === "start" && global.get('current_game.game_state') !== "start") {
